mapper.select:
select t.id, t.create_user_id as createUserId, t.create_user_name as createUserName, t.create_time as createTime, t.update_user_id as updateUserId, t.update_user_name as updateUserName, t.update_time as updateTime, t.version, t.is_deleted as isDeleted, t.code, t.source_id as sourceId, t.source_code as sourceCode, t.source_type as sourceType, t.type, t.is_use as isUse, t.pack_status as packStatus, t.is_difference as isDifference, t.is_move_warehouse as isMoveWarehouse, t.sku_species_qty as skuSpeciesQty, t.total_qty as totalQty, t.remark, pt.supplier_id as supplierId, pt.supplier_name as supplierName from after_sale_pack t left join po_return pt on t.source_id = pt.id and pt.is_deleted = false WHERE 1 = 1 and t.is_deleted = false
AND ${params.sqlMap.default}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
t.update_time DESC
